  'Quay lại Kết nối dịch vụ': { en: 'Back to Service connections', zh: '返回服务连接', ja: 'サービス接続に戻る', ko: '서비스 연결로 돌아가기', es: 'Volver a Conexiones de servicios', fr: 'Retour aux Connexions de services', de: 'Zurück zu Dienstverbindungen', th: 'กลับไปที่การเชื่อมต่อบริการ', id: 'Kembali ke Koneksi layanan' },
