  'Chính chủ {vendor}': { en: 'Official by {vendor}', zh: '{vendor} 官方', ja: '{vendor} 公式', ko: '{vendor} 공식', es: 'Oficial de {vendor}', fr: 'Officiel {vendor}', de: 'Offiziell von {vendor}', th: 'ทางการจาก {vendor}', id: 'Resmi dari {vendor}' },
